import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class Effect {
        long a, b;
        Effect(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static long ceilDiv(long numerator, long denominator) {
        long q = numerator / denominator;
        long r = numerator % denominator;
        if (r > 0) q++;
        return q;
    }

    static long repeatedEffect(long a, long b, long times, long x) {
        long resultA = 1, resultB = 0;
        long baseA = a % MOD, baseB = b % MOD;

        while (times > 0) {
            if ((times & 1L) != 0) {
                resultB = (baseA * resultB + baseB) % MOD;
                resultA = baseA * resultA % MOD;
            }
            baseB = (baseA * baseB + baseB) % MOD;
            baseA = baseA * baseA % MOD;
            times >>= 1;
        }
        return (resultA * (x % MOD) + resultB) % MOD;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = (int) fs.nextLong();
        int m = (int) fs.nextLong();
        long k = fs.nextLong();

