        for (int i = 0; i < n; i++) spellB[i] = fs.nextLong();

        Effect[] spells = new Effect[n];
        for (int i = 0; i < n; i++) spells[i] = new Effect(spellA[i], spellB[i]);
        Arrays.sort(spells, (u, v) -> {
            int cmp = Long.compare(u.a, v.a);
            return cmp != 0 ? cmp : Long.compare(v.b, u.b);
        });

