                Effect last = hull.get(hull.size() - 1);
                long crossing = ceilDiv(last.b - e.b, e.a - last.a);
                if (hull.size() > 1 && crossing <= starts.get(starts.size() - 1)) {
                    hull.remove(hull.size() - 1);
                    starts.remove(starts.size() - 1);
                } else {
                    hull.add(e);
                    starts.add(hull.size() == 1 ? Long.MIN_VALUE : crossing);
                    break;
                }
            }
            if (hull.isEmpty()) {
                hull.add(e);
                starts.add(Long.MIN_VALUE);
            }
        }

        long[] start = new long[hull.size()];
        for (int i = 0; i < hull.size(); i++) start[i] = starts.get(i);

