        for (int i = 0; i < m; i++) mealB[i] = fs.nextLong();

        Effect[] meals = new Effect[m];
        for (int i = 0; i < m; i++) meals[i] = new Effect(mealA[i], mealB[i]);

        Arrays.sort(meals, (u, v) -> {
            if (u.a == 1 && v.a != 1) return -1;
            if (v.a == 1 && u.a != 1) return 1;
            if (u.a == 1) return 0;
            long left = u.b * (v.a - 1);
            long right = v.b * (u.a - 1);
            return Long.compare(right, left);
        });

        long finalA = 1, finalB = 0;
        for (Effect e : meals) {
            long a = e.a % MOD, b = e.b % MOD;
            finalB = (a * finalB + b) % MOD;
            finalA = a * finalA % MOD;
        }

        int q = (int) fs.nextLong();
        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < q; qi++) {
            long x = fs.nextLong();
            long remaining = k;

            while (remaining > 0) {
                int lo = 0, hi = start.length;
                while (lo + 1 < hi) {
                    int mid = (lo + hi) >>> 1;
                    if (start[mid] <= x) lo = mid;
                    else hi = mid;
                }

                Effect current = hull.get(lo);
                if (lo == hull.size() - 1) {
                    x = repeatedEffect(current.a, current.b, remaining, x);
                    remaining = 0;
                    break;
                }

                long threshold = start[lo + 1];
                if (current.a == 1) {
                    long stepsToNext = (threshold - x + current.b - 1) / current.b;
                    long steps = Math.min(remaining, stepsToNext);
                    x += steps * current.b;
                    remaining -= steps;
                } else {
                    x = current.a * x + current.b;
                    remaining--;
                }
            }

            long answer = (finalA * (x % MOD) + finalB) % MOD;
            out.append(answer).append('\n');
        }

        System.out.print(out);
    }
